2	
3	use dynamo_kv_hashing::compute_salt_hash;
4	use kvbm_logical::KvbmSequenceHashProvider;
5	use kvbm_logical::SequenceHash;
6	use kvbm_logical::blocks::ImmutableBlock;
7	use kvbm_logical::blocks::MutableBlock;
8	use kvbm_logical::events::EventsManager;
9	use kvbm_logical::events::KvCacheEvent;
10	use kvbm_logical::integrations::DecodeOutcome;
11	use kvbm_logical::integrations::SchedulableSequence;
12	use kvbm_logical::integrations::ScheduleError;
13	use kvbm_logical::manager::BlockManager;
14	use kvbm_logical::pools::BlockDuplicationPolicy;
15	use kvbm_logical::registry::BlockRegistry;
16	use tokio::sync::broadcast;
17	
18	use crate::view::KvView;
19	
20	/// Broadcast capacity for the opt-in KV-event feed. Generous: the scheduler
21	/// drains it every step, but a step can register/evict many blocks, and a
22	/// dropped event silently desyncs the router's prefix tree. Only allocated on
23	/// the [`BlockPool::with_events`] path.
24	const KV_EVENT_CHANNEL_CAPACITY: usize = 65_536;
25	
26	/// Logical KV block pool: a `BlockManager` plus the reserved padding block.
27	///
28	/// Owns no GPU memory — the physical layout (full-attention `KvBuffer`,
29	/// MLA dual ckv/kpe buffers, ...) lives with the consumer and is indexed
30	/// by the block IDs this pool hands out.
31	pub struct BlockPool {
32	    block_manager: BlockManager<()>,
33	    block_size: usize,
34	    padding_block_id: usize,
35	}
36	
37	impl BlockPool {
38	    pub fn new(block_size: usize, num_blocks: usize) -> anyhow::Result<Self> {
39	        Self::build(block_size, num_blocks, BlockRegistry::builder().build())
40	    }
41	
42	    /// Like [`new`](Self::new), but the pool also emits block store/remove
43	    /// events for an out-of-band cache-aware router, returned as a raw broadcast
44	    /// receiver to drain synchronously. The stream carries `Create` events too
45	    /// (the emission policy can't separate them) — the consumer ignores `Create`
46	    /// and sources richer store events from the seal site, and maps the lineage
47	    /// hash in each `Remove` back to the router's `sequence_hash`. OFF by
48	    /// default: plain single-machine serving uses [`new`](Self::new) and pays
49	    /// neither the per-block event attachment nor the channel.
50	    pub(crate) fn with_events(
51	        block_size: usize,
52	        num_blocks: usize,
53	    ) -> anyhow::Result<(Self, broadcast::Receiver<KvCacheEvent>)> {
54	        // Default emission policy is AllEventsPolicy (every block tracked).
55	        let events = Arc::new(
56	            EventsManager::builder()
57	                .channel_capacity(KV_EVENT_CHANNEL_CAPACITY)
58	                .build(),
59	        );
60	        let rx = events.subscribe_receiver();
61	        let registry = BlockRegistry::builder().event_manager(events).build();
62	        let pool = Self::build(block_size, num_blocks, registry)?;
63	        Ok((pool, rx))
64	    }
65	
66	    fn build(
67	        block_size: usize,
68	        num_blocks: usize,
69	        registry: BlockRegistry,
70	    ) -> anyhow::Result<Self> {
71	        anyhow::ensure!(num_blocks >= 2, "need at least 2 blocks (1 for padding)");
72	
73	        let block_manager = BlockManager::builder()
74	            .block_count(num_blocks)
75	            .block_size(block_size)
76	            .registry(registry)
77	            .duplication_policy(BlockDuplicationPolicy::Allow)
78	            .with_lru_backend()
79	            .build()
80	            .map_err(|e| anyhow::anyhow!("BlockManager build failed: {e}"))?;
81	
82	        // Reserve block 0 as CUDA Graph padding slot.
83	        let padding_blocks = block_manager
84	            .allocate_blocks(1)
85	            .ok_or_else(|| anyhow::anyhow!("failed to allocate padding block"))?;
86	        let padding_block_id = padding_blocks[0].block_id();
87	        let padding_complete = padding_blocks
88	            .into_iter()
89	            .next()
90	            .unwrap()
91	            .stage(SequenceHash::default(), block_size)
92	            .map_err(|e| anyhow::anyhow!("padding block stage failed: {e}"))?;
93	        // Register so it stays alive (ImmutableBlock RAII keeps it out of the
94	        // free pool), then leak — padding lives for the lifetime of the engine.
95	        std::mem::forget(block_manager.register_block(padding_complete));
96	
97	        Ok(Self {
98	            block_manager,
99	            block_size,
100	            padding_block_id,
101	        })
102	    }
