390	impl RequestKv {
391	    // ── Prefix cache ───────────────────────────────────────────────────
392	
393	    /// Match the prompt's full blocks against registered blocks and skip
394	    /// their prefill. Returns the number of cached tokens; `kv_position()`
395	    /// advances by the same amount. Must be called on a fresh request,
396	    /// before the first `schedule_prefill`.
397	    ///
398	    /// Matching always leaves at least one prompt token uncached so the
399	    /// final prefill chunk can emit the first generated token.
400	    pub fn match_and_add_prefix(&mut self, pool: &BlockPool) -> anyhow::Result<usize> {
401	        self.match_and_add_prefix_up_to(pool, usize::MAX)
402	    }
403	
404	    /// Match and attach no more than `max_blocks` of the resident prefix.
405	    ///
406	    /// The underlying sequence still enforces the final-token cap. A caller
407	    /// can hold a [`PrefixProbe`] while invoking this method to ensure the
408	    /// selected blocks remain resident between joint-state lookup and attach.
409	    pub fn match_and_add_prefix_up_to(
410	        &mut self,
411	        pool: &BlockPool,
412	        max_blocks: usize,
413	    ) -> anyhow::Result<usize> {
414	        let blocks = self
415	            .seq
416	            .match_and_add_prefix_up_to(&pool.block_manager, max_blocks)
417	            .map_err(|e| anyhow::anyhow!("match_and_add_prefix_up_to: {e}"))?;
418	        // Prefix-hit blocks are already in the router's tree (whoever first
419	        // sealed them stored them, and a GPU hit means they were never evicted),
420	        // so the store-event cursor skips them.
421	        self.emitted_blocks = self.seq.assigned_blocks();
422	        Ok(blocks * self.seq.block_size())
423	    }
