930	    /// CPU-only shape of issue #681: 160 request pages, a 1643-token prompt
931	    /// split into 1024 + 619 prefill chunks, 512 output tokens, and 17-token
932	    /// speculative verify spans. A completed request must leave enough clean
933	    /// pages for the identical request to finish again.
934	    #[test]
935	    fn issue_681_profiled_capacity_reuses_blocks_across_requests() {
936	        // BlockPool reserves one additional CUDA-graph padding page.
937	        let pool = BlockPool::new(16, 161).unwrap();
938	        assert_eq!(pool.max_request_blocks(), 160);
939	        let baseline = pool.available_blocks();
940	        let prompt = (0..1643).map(|i| 30_000 + i).collect::<Vec<_>>();
941	
942	        for round in 0..2 {
943	            complete_non_retained_speculative_request(&pool, &prompt, 512);
944	            assert_eq!(
945	                pool.available_blocks(),
946	                baseline,
947	                "issue #681 request {round} did not release its KV pages"
948	            );
949	        }
950	    }
