2	///
3	/// Pure value type — no GPU, no allocation.
4	#[derive(Clone, Copy, Debug)]
5	pub struct KvLayout {
6	    pub page_size: usize,
7	    pub num_layers: usize,
8	    pub num_kv_heads: usize,
9	    pub head_dim: usize,
10	    /// Elements in one K (or V) block: page_size × num_kv_heads × head_dim.
11	    pub kv_block_len: usize,
12	    /// Elements between layers within a page: 2 × kv_block_len (K then V).
13	    pub layer_stride: usize,
14	    /// Elements per page (all layers): num_layers × layer_stride.
15	    pub page_stride: usize,
16	}
17	
18	impl KvLayout {
19	    pub fn new(num_layers: usize, num_kv_heads: usize, head_dim: usize, page_size: usize) -> Self {
20	        let kv_block_len = page_size * num_kv_heads * head_dim;
21	        let layer_stride = 2 * kv_block_len;
22	        let page_stride = num_layers * layer_stride;
23	        Self {
24	            page_size,
25	            num_layers,
26	            num_kv_heads,
27	            head_dim,
28	            kv_block_len,
29	            layer_stride,
30	            page_stride,
31	        }
32	    }
33	}
